import{describe,it,expect}from"vitest";import{excavationsData,filterExcavations,sortExcavations,groupExcavationsByPeriod,groupExcavationsByState,getUniqueStates,getUniquePeriods}from"../../frontend/excavations/excavations.js";const REQUIRED_FIELDS=["id","title","state","stateCode","location","period","discoveryYear","archaeologistOrAgency","artifactsDiscovered","image","description","significance","tags"];describe("Archaeological Excavation Data Integrity",()=>{it("contains at least 25 excavation site entries in the dataset",()=>{expect(excavationsData.length).toBeGreaterThanOrEqual(25)}),it("every excavation site contains all required fields with non-empty values",()=>{excavationsData.forEach((e,t)=>{REQUIRED_FIELDS.forEach(a=>{expect(e,`Excavation site at index ${t} missing field ${a}`).toHaveProperty(a),"tags"===a?(expect(Array.isArray(e.tags)).toBe(!0),expect(e.tags.length).toBeGreaterThan(0)):"discoveryYear"===a?(expect(typeof e[a]).toBe("number"),expect(e[a]).toBeGreaterThan(1800)):(expect(typeof e[a]).toBe("string"),expect(e[a].trim().length).toBeGreaterThan(0))})})}),it("all excavation site IDs are unique",()=>{const e=excavationsData.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length)}),it("all excavation site titles are unique",()=>{const e=excavationsData.map(e=>e.title),t=new Set(e);expect(t.size).toBe(e.length)}),it("includes key archaeological excavation sites mentioned in requirements (Dholavira, Lothal, Rakhigarhi, Kalibangan, Keezhadi, Sinauli)",()=>{const e=new Set(excavationsData.map(e=>e.id));expect(e.has("dholavira")).toBe(!0),expect(e.has("lothal")).toBe(!0),expect(e.has("rakhigarhi")).toBe(!0),expect(e.has("kalibangan")).toBe(!0),expect(e.has("keezhadi")).toBe(!0),expect(e.has("sinauli")).toBe(!0)}),it("spans multiple historical eras (Prehistoric, Neolithic, Indus Valley, Iron Age/Sangam, Early Historic)",()=>{const e=new Set(excavationsData.map(e=>e.period));expect(e.has("Indus Valley Civilisation")).toBe(!0),expect(e.has("Iron Age & Sangam Era")).toBe(!0),expect(e.has("Early Historic & Classical Era")).toBe(!0),expect(e.has("Neolithic & Chalcolithic Era")).toBe(!0),expect(e.has("Prehistoric & Paleolithic Era")).toBe(!0)})}),describe("Archaeological Excavation Search & Filtering Algorithms",()=>{it("returns all excavation sites when search query and filters are default",()=>{const e=filterExcavations(excavationsData);expect(e.length).toBe(excavationsData.length)}),it("filters excavations by search query (e.g. dockyard or Dholavira)",()=>{const e=filterExcavations(excavationsData,{search:"dockyard"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=[e.title,e.location,e.state,e.period,e.archaeologistOrAgency,e.artifactsDiscovered,e.description,e.significance,...e.tags||[]].some(e=>e&&e.toLowerCase().includes("dockyard"));expect(t).toBe(!0)})}),it("filters excavations by state code (e.g. gj for Gujarat)",()=>{const e=filterExcavations(excavationsData,{state:"gj"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.stateCode).toBe("gj")})}),it("filters excavations by historical period",()=>{const e=filterExcavations(excavationsData,{period:"indus valley civilisation"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.period.toLowerCase()).toBe("indus valley civilisation")})}),it("combines search, state, and period filters correctly",()=>{const e=filterExcavations(excavationsData,{search:"signboard",state:"gj",period:"indus valley civilisation"});expect(e.length).toBe(1),expect(e[0].id).toBe("dholavira")}),it("returns empty array when search query matches no item",()=>{const e=filterExcavations(excavationsData,{search:"nonexistentexcavationsite999"});expect(e.length).toBe(0)}),it("handles invalid or empty inputs gracefully",()=>{expect(filterExcavations(null)).toEqual([]),expect(filterExcavations(void 0)).toEqual([]),expect(filterExcavations([])).toEqual([])})}),describe("Archaeological Excavation Sorting & Grouping Utilities",()=>{it("sorts excavations by discovery year ascending",()=>{const e=sortExcavations(excavationsData,"year-asc");for(let t=1;t<e.length;t++)expect(e[t-1].discoveryYear).toBeLessThanOrEqual(e[t].discoveryYear)}),it("sorts excavations by discovery year descending",()=>{const e=sortExcavations(excavationsData,"year-desc");for(let t=1;t<e.length;t++)expect(e[t-1].discoveryYear).toBeGreaterThanOrEqual(e[t].discoveryYear)}),it("sorts excavations alphabetically by title name",()=>{const e=sortExcavations(excavationsData,"name-asc");for(let t=1;t<e.length;t++)expect(e[t-1].title.localeCompare(e[t].title)).toBeLessThanOrEqual(0)}),it("groups excavations by period correctly",()=>{const e=groupExcavationsByPeriod(excavationsData);expect(e["Indus Valley Civilisation"]).toBeDefined(),expect(e["Iron Age & Sangam Era"]).toBeDefined(),expect(e["Prehistoric & Paleolithic Era"]).toBeDefined()}),it("groups excavations by state correctly",()=>{const e=groupExcavationsByState(excavationsData);expect(e.Gujarat).toBeDefined(),expect(e["Tamil Nadu"]).toBeDefined(),expect(e.Haryana).toBeDefined()}),it("extracts unique states sorted alphabetically",()=>{const e=getUniqueStates(excavationsData);expect(e.length).toBeGreaterThanOrEqual(6),expect(e[0]).toHaveProperty("code"),expect(e[0]).toHaveProperty("name");for(let t=1;t<e.length;t++)expect(e[t-1].name.localeCompare(e[t].name)).toBeLessThanOrEqual(0)}),it("extracts unique periods sorted alphabetically",()=>{const e=getUniquePeriods(excavationsData);expect(e.length).toBeGreaterThan(0),expect(e).toContain("Indus Valley Civilisation"),expect(e).toContain("Iron Age & Sangam Era")})});